/* ==== CEVIRILER SONU ==== */









function dilVar(k) {
  for (var i = 0; i < DILLER.length; i++) if (DILLER[i].kod === k) return true;
  return false;
}

function T(s) {
  if (LANG === 'tr' || s === null || s === undefined) return s;
  var d = SOZLUK[LANG];
  if (!d) return s;
  var v = d[s];
  return v === undefined ? s : v;
}

function loadLang() {
  try {
    var v = localStorage.getItem(LANGKEY);
    if (v && dilVar(v)) LANG = v;
  } catch (e) { }
}

function setLang(l) {
  if (!dilVar(l)) return;
  LANG = l;
  try { localStorage.setItem(LANGKEY, l); } catch (e) { }
  /* pişmiş katmanlarda yazı var — hepsi yenilensin */
  if (typeof invalidateLayers === 'function') invalidateLayers();
  if (typeof SHOP !== 'undefined') SHOP.bake = null;
}
